import { twMerge } from "tailwind-merge";
import React from "react";
import * as icons from "./icons";

export type IconType = keyof typeof icons;

type Props = {
  icon: IconType;
  className?: string;
  containerClassName?: string;
  children?: React.ReactNode;
  size?: number | string;
  style?: React.CSSProperties;
};

const Icon = React.forwardRef<SVGSVGElement | HTMLDivElement, Props>((props, ref) => {
  const { className, containerClassName, icon, children = null, size, style, ...restProps } = props;

  const IconComponent = icons[icon] as React.ComponentType<{
    className?: string;
    ref?: React.Ref<SVGSVGElement | HTMLDivElement>;
    size?: number | string;
    style?: React.CSSProperties;
    [key: string]: any;
  }>;

  if (!IconComponent) {
    console.warn(`Icon "${icon}" not found`);
    return null;
  }

  return (
    <IconComponent
      className={twMerge("fill-current", className)}
      ref={ref}
      size={size}
      style={style}
      {...restProps}
    />
  );
});

Icon.displayName = "Icon";

export default Icon;
