"use client";
import React, { useEffect, useState } from "react";

type RoadmapExtendIconProps = {
  className?: string;
  size?: number | string; // Allow custom size
};

const RoadmapExtendIcon = React.forwardRef<HTMLDivElement, RoadmapExtendIconProps>(
  ({ className, size, ...props }, ref) => {
    const [svgContent, setSvgContent] = useState<string>("");

    useEffect(() => {
      // Load SVG content dynamically from public folder
      fetch("/roadmap-extend.svg")
        .then((res) => res.text())
        .then((text) => {
          // Parse SVG and remove text elements (fill="#000000")
          const parser = new DOMParser();
          const doc = parser.parseFromString(text, "image/svg+xml");
          const svgElement = doc.querySelector("svg");
          if (svgElement) {
            // Remove all text groups (groups with fill="#000000")
            const textGroups = svgElement.querySelectorAll('g[fill="#000000"]');
            textGroups.forEach((group) => group.remove());

            // Add our custom styles for interactive paths
            const style = document.createElement("style");
            style.textContent = `
              #path1,
              #path2,
              #path3,
              #path4,
              .path1,
              .path2,
              .path3,
              .path4 {
                cursor: pointer;
                transition: opacity 0.3s ease, filter 0.3s ease;
              }
              #path1:hover,
              #path2:hover,
              #path3:hover,
              #path4:hover,
              .path1:hover,
              .path2:hover,
              .path3:hover,
              .path4:hover {
                opacity: 0.85;
                filter: brightness(1.1);
              }
            `;
            svgElement.insertBefore(style, svgElement.firstChild);
            setSvgContent(svgElement.outerHTML);
          }
        })
        .catch((err) => {
          console.error("Error loading SVG:", err);
        });
    }, []);

    if (!svgContent) {
      return (
        <div className={className} style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div className="animate-pulse text-gray-400">Loading roadmap...</div>
        </div>
      );
    }

    const sizeStyle = size
      ? typeof size === "number"
        ? { width: `${size}px`, height: "auto" }
        : { width: size, height: "auto" }
      : {};

    return (
      <div
        ref={ref}
        className={className}
        dangerouslySetInnerHTML={{ __html: svgContent }}
        style={{ width: "100%", height: "100%", ...sizeStyle }}
        {...props}
      />
    );
  }
);

RoadmapExtendIcon.displayName = "RoadmapExtendIcon";

export default RoadmapExtendIcon;

