"use client";
import React, { useEffect, useRef, useState } from "react";
import PathContent from "./path-content";
import Icon from "./icon-component";
import { motion, useInView } from "framer-motion";

const LearningPathSection = () => {
  const ref = useRef<HTMLDivElement>(null);
  const sectionRef = useRef<HTMLDivElement>(null);
  const [selectedPath, setSelectedPath] = useState("level1");

  // Use framer-motion's useInView to detect the section visibility
  const isInView = useInView(sectionRef, { once: true, margin: "-50px" });

  useEffect(() => {
    if (ref.current) {
      const pathContent = document.getElementById("path-content");
      // Find paths by id or class
      const path1 = ref.current.querySelector("#path1") as HTMLElement;
      const path2 = ref.current.querySelector("#path2") as HTMLElement;
      const path3 = ref.current.querySelector("#path3") as HTMLElement;
      const path4 = ref.current.querySelector("#path4") as HTMLElement;

      console.log("path1", ref.current);

      // Add interactive styles for each path
      const handleMouseEnter1 = () => {
        if (path1) {
          path1.style.opacity = "0.85";
          path1.style.filter = "brightness(1.1)";
        }
      };
      const handleMouseLeave1 = () => {
        if (path1) {
          path1.style.opacity = "1";
          path1.style.filter = "none";
        }
      };
      const handleMouseEnter2 = () => {
        if (path2) {
          path2.style.opacity = "0.85";
          path2.style.filter = "brightness(1.1)";
        }
      };
      const handleMouseLeave2 = () => {
        if (path2) {
          path2.style.opacity = "1";
          path2.style.filter = "none";
        }
      };
      const handleMouseEnter3 = () => {
        if (path3) {
          path3.style.opacity = "0.85";
          path3.style.filter = "brightness(1.1)";
        }
      };
      const handleMouseLeave3 = () => {
        if (path3) {
          path3.style.opacity = "1";
          path3.style.filter = "none";
        }
      };
      const handleMouseEnter4 = () => {
        if (path4) {
          path4.style.opacity = "0.85";
          path4.style.filter = "brightness(1.1)";
        }
      };
      const handleMouseLeave4 = () => {
        if (path4) {
          path4.style.opacity = "1";
          path4.style.filter = "none";
        }
      };

      if (path1) {
        path1.style.cursor = "pointer";
        path1.style.transition = "opacity 0.3s ease, filter 0.3s ease";
        path1.addEventListener("mouseenter", handleMouseEnter1);
        path1.addEventListener("mouseleave", handleMouseLeave1);
      }
      if (path2) {
        path2.style.cursor = "pointer";
        path2.style.transition = "opacity 0.3s ease, filter 0.3s ease";
        path2.addEventListener("mouseenter", handleMouseEnter2);
        path2.addEventListener("mouseleave", handleMouseLeave2);
      }
      if (path3) {
        path3.style.cursor = "pointer";
        path3.style.transition = "opacity 0.3s ease, filter 0.3s ease";
        path3.addEventListener("mouseenter", handleMouseEnter3);
        path3.addEventListener("mouseleave", handleMouseLeave3);
      }
      if (path4) {
        path4.style.cursor = "pointer";
        path4.style.transition = "opacity 0.3s ease, filter 0.3s ease";
        path4.addEventListener("mouseenter", handleMouseEnter4);
        path4.addEventListener("mouseleave", handleMouseLeave4);
      }

      const handleClick1 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth", inline: "nearest" });
        setSelectedPath("level1");
      };
      const handleClick2 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level2.5");
      };
      const handleClick3 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level2");
      };
      const handleClick4 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level3");
      };

      if (path1) path1.addEventListener("click", handleClick1);
      if (path2) path2.addEventListener("click", handleClick2);
      if (path3) path3.addEventListener("click", handleClick3);
      if (path4) path4.addEventListener("click", handleClick4);

      // Cleanup: remove all event listeners
      return () => {
        if (path1) {
          path1.removeEventListener("click", handleClick1);
          path1.removeEventListener("mouseenter", handleMouseEnter1);
          path1.removeEventListener("mouseleave", handleMouseLeave1);
        }
        if (path2) {
          path2.removeEventListener("click", handleClick2);
          path2.removeEventListener("mouseenter", handleMouseEnter2);
          path2.removeEventListener("mouseleave", handleMouseLeave2);
        }
        if (path3) {
          path3.removeEventListener("click", handleClick3);
          path3.removeEventListener("mouseenter", handleMouseEnter3);
          path3.removeEventListener("mouseleave", handleMouseLeave3);
        }
        if (path4) {
          path4.removeEventListener("click", handleClick4);
          path4.removeEventListener("mouseenter", handleMouseEnter4);
          path4.removeEventListener("mouseleave", handleMouseLeave4);
        }
      };
    }
  }, []);

  return (
    <section className="mx-auto w-full max-w-7xl bg-transparent py-12">
      <div>
        <motion.div
          ref={sectionRef}
          initial={{ opacity: 0, y: 60 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.75, ease: "easeOut" }}
          className="container mx-auto flex flex-col items-center justify-center space-y-6"
        >
          {/* Title */}
          <motion.h2
            className="mb-1 text-center text-3xl font-bold leading-tight text-slate-700 md:text-4xl lg:text-5xl"
            initial={{ opacity: 0, y: 40 }}
            animate={isInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.55, delay: 0.08 }}
          >
            LỘ TRÌNH TRỞ THÀNH KỸ SƯ AI TOÀN NĂNG
          </motion.h2>
          {/* Subtitle/Description */}
          <motion.p
            className="max-w-3xl text-balance text-center text-sm font-medium text-muted-foreground md:text-base"
            initial={{ opacity: 0, y: 32 }}
            animate={isInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.62, delay: 0.2 }}
          >
            Theo nghiên cứu, chỉ 5% dân số thế giới có thiên phú phù hợp với
            ngành công nghệ AI, tuy nhiên, kể cả khi bạn có tài năng thiên bẩm,
            con đường bạn đi cũng không hề dễ dàng
            {/* <br /> ( PSG.TS Nguyễn Phi Lê
            - Đại học Bách Khoa Hà Nội Điều hành Viện nghiên cứu trí tuệ nhân
            tạo ) */}
          </motion.p>
        </motion.div>

        <div className="relative w-full overflow-x-auto overflow-y-visible py-8 px-4">
          {/* Path selector */}
          <motion.div
            className="container mx-auto flex w-full items-center justify-center"
            initial={{ opacity: 0, scale: 0.97 }}
            animate={isInView ? { opacity: 1, scale: 1 } : {}}
            transition={{ duration: 0.68, delay: 0.3 }}
          >
            <div className="w-full" style={{ maxWidth: "100%", minHeight: "500px" }}>
              <Icon
                icon="roadmapExtend"
                className="w-full h-auto"
                style={{ 
                  minWidth: "1400px", 
                  width: "100%", 
                  maxWidth: "100%",
                  height: "auto"
                }}
                ref={ref as React.RefObject<HTMLDivElement>}
              />
            </div>
          </motion.div>
        </div>
      </div>

      <motion.div
        id="path-content"
        className="mt-8"
        initial={{ opacity: 0, y: 40 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6, delay: 0.38 }}
      >
        <PathContent selectedPath={selectedPath} />
      </motion.div>
    </section>
  );
};

export default LearningPathSection;
